// Purpose: ROW-018 (REQ-035) — through the check endpoint, a misspelled capitalised first word of a bullet
// line, a heading line, a numbered line, or after a colon (Gestion in a bullet, Ubicacion before a colon)
// is flagged, while the same kind of name in mid-sentence is not.
// Provenance: hand-authored from REQ-035's fail-if examples, A-031, A-046 and A-050; bullet characters
// typed from what word processors paste; misspellings fresh per run (freshName) or generated by the
// dictionary oracle (accent-stripped forms, title-cased and checked); no expected value comes from the
// product.
//
// Test argument
// ROW-018 promise: a misspelled capitalised first word of a bullet line, a heading line, a numbered
//   line or a word after a colon (Gestion in a bullet, Ubicacion before a colon) is flagged (REQ-035
//   fail-if arm 1 as narrowed by A-050; A-031 "a sentence starts ... at the start of every line (after
//   any bullet character or numbering), and after a colon"; A-046 after a colon a capitalised unknown
//   word is flagged when its accent-restored form is a dictionary word).
// ROW-018 wrong product: one whose sentence starts are only ". ? ! …", so a fresh misspelling opening a
//   bullet or a heading after a line with no full stop is taken as a mid-sentence name and passes; one
//   that does not step over the bullet or the number ("• Valtermoz", "2) Valtermoz") to find the first
//   word; or one that treats every word after a colon as a name, so "Área: Gestion" passes.
// ROW-018 given: a job offer's layout — heading lines, bullet lines under seven bullet characters,
//   numbered lines in three styles, "Label: value" lines — each opening with a fresh capitalised
//   misspelling (not accent-restorable, so only the line-start rule can flag it) or a title-cased
//   accent-stripped word, the row's own Gestion bullet and Ubicacion: line, and an accent-restorable
//   misspelling after a colon; no line ends in a full stop; decoys in the same text: correct
//   capitalised words opening lines and fresh names mid-line (unflagged); when: POST /api/check;
//   then: exactly the misspelled line openings and the misspelling after the colon are flagged.
// ROW-018 controls: the same misspellings in lower case mid-sentence are flagged — they are
//   misspellings to the product, so the target's verdict is about where a sentence starts.
// ROW-018 technique: every line shape REQ-035 names, fresh misspellings each run, the row's own
//   examples; exact comparison with decoys (the same fresh-name shape mid-line must not be flagged).
// cases: ROW-018 target=ROW-018-misspelled-first-words-of-bullet-heading-numbered-lines-and-after-a-colon-flagged control=ROW-018-control-the-same-misspellings-in-lower-case-mid-sentence-flagged

import { test } from '@playwright/test';
import { accentPopulation, asActor, freshRandom, isDictionaryWord, type Rng } from './harness';
import { Offer, expectExact, fillers, freshName, requireDictionary, requireNotDictionary, titleCase } from './names-terms-helpers';

const BULLETS = ['• ', '- ', '* ', '· ', '◦ ', '▪ ', '•\t'];
const NUMBERS = ['1. ', '2) ', '3.- '];
const LABELS = ['Área', 'Puesto', 'Requisitos', 'Funciones', 'Horario'];

function stripped(rng: Rng, n: number): string[] {
  return rng
    .shuffle(accentPopulation())
    .map((p) => ({ bad: titleCase(p.stripped), good: titleCase(p.word) }))
    .filter((p) => !isDictionaryWord(p.bad) && isDictionaryWord(p.good))
    .slice(0, n)
    .map((p) => p.bad);
}

test('ROW-018-misspelled-first-words-of-bullet-heading-numbered-lines-and-after-a-colon-flagged', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  requireNotDictionary(['Gestion', 'Ubicacion'], 'ROW-018 named misspellings');
  requireDictionary([...LABELS, 'Gestión', 'Ubicación', 'Responsabilidades', 'Beneficios'], 'ROW-018 correct line openings');
  const accentBad = stripped(rng, 20); // enough for every line opening below and the colon values
  const misspelling = () => (rng.int(2) === 0 ? freshName(rng) : accentBad.pop() ?? freshName(rng));

  const o = new Offer().flag(freshName(rng), 'fresh misspelling opening a heading line').put(' ' + fillers(rng, 2) + '\n');
  o.keep('Responsabilidades', 'correct heading line').put('\n');
  // bullet lines: one per bullet character, plus the row's own Gestion bullet
  for (const b of rng.shuffle(BULLETS)) {
    o.put(b).flag(misspelling(), `misspelled first word after bullet ${JSON.stringify(b)}`).put(' ' + fillers(rng, 2) + ' ').keep(freshName(rng), 'fresh name mid-line').put(' ' + fillers(rng, 1) + '\n');
  }
  o.put('• ').flag('Gestion', 'Gestion opening a bullet').put(' ' + fillers(rng, 2) + '\n');
  o.put('• ').keep('Gestión', 'Gestión opening a bullet').put(' ' + fillers(rng, 2) + '\n');
  // a heading line with no full stop on the line before it
  o.put('\n').flag(misspelling(), 'misspelled heading line').put('\n');
  o.keep('Beneficios', 'correct heading line').put('\n');
  // numbered lines
  for (const n of rng.shuffle(NUMBERS)) {
    o.put(n).flag(misspelling(), `misspelled first word after numbering ${JSON.stringify(n)}`).put(' ' + fillers(rng, 2) + '\n');
  }
  // Label: value lines — the row's Ubicacion before a colon, misspelled labels, an accent-restorable value
  o.flag('Ubicacion', 'Ubicacion before a colon').put(': ' + fillers(rng, 2) + '\n');
  o.keep('Ubicación', 'Ubicación before a colon').put(': ' + fillers(rng, 1) + '\n');
  o.flag(freshName(rng), 'misspelled label before a colon').put(': ' + fillers(rng, 2) + '\n');
  o.put(rng.pick(LABELS) + ': ').flag('Gestion', 'Gestion after a colon').put(' ' + fillers(rng, 2) + '\n');
  for (const bad of accentBad.slice(0, 3)) o.put(rng.pick(LABELS) + ': ').flag(bad, 'accent-restorable misspelling after a colon').put(' ' + fillers(rng, 1) + '\n');
  o.put(fillers(rng, 3, { capital: true }));
  await expectExact(o, `ROW-018: misspelled capitalised first words of bullet, heading and numbered lines and after a colon are flagged (seed ${rng.seed})`);
});

test('ROW-018-control-the-same-misspellings-in-lower-case-mid-sentence-flagged', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const o = new Offer().put(fillers(rng, 2, { capital: true }) + ' ').flag('gestion', 'gestion lower case').put(' ' + fillers(rng, 1) + ' ').flag('ubicacion', 'ubicacion lower case');
  for (const w of [freshName(rng), freshName(rng), ...stripped(rng, 2)]) o.put(' ' + fillers(rng, 1) + ' ').flag(w.toLowerCase(), 'misspelling in lower case mid-sentence');
  o.put(' ' + fillers(rng, 2) + '.');
  await expectExact(o, `ROW-018 control: the line-opening misspellings in lower case mid-sentence are flagged (seed ${rng.seed})`);
});
